        self.assertEqual(status, 201)
        self.assertEqual(payload["stream"], "a")
        self.assertEqual(payload["auto_watermark_lag_ms"], 500)
        # zero is a valid lag
        status, payload = self.create("z", 1000, 0, auto_watermark_lag_ms=0)
        self.assertEqual(status, 201)
